method.description:
Creates an unattached element in this label's layout. Parses any pending source first, so the new element and its parent can be prepared before the first layout update. Returns [code]null[/code] for an invalid name or a source that could not be parsed. See [method HTMLLayout.create_element].
[codeblock]
var item: HTMLElement = label.create_element("li")
var list: HTMLElement = label.query_selector("#quests")
if item != null and list != null:
	item.set_attribute("data-quest", "intro")
	item.set_text_content("Find the entrance")
	list.append_child(item)
[/codeblock]
